        const model = { id: 'fixture', name: 'fixture', api: 'openai-responses', provider: 'openai',
            baseUrl: 'http://127.0.0.1:1/v1', reasoning: false, input: ['text'],
            contextWindow: 1000000, maxTokens: 200000,
