        const start = performance.now();
        try {
            await (await fetch(url, { signal: AbortSignal.timeout(1000) })).text();
            probes.push({ ok: true, ms: performance.now() - start });
        } catch (error) {
            probes.push({ ok: false, error: error.name, ms: performance.now() - start });
        }
    }
    const wallMs = performance.now() - started;
    const cpuMs = state.exited ? null : mainThreadCpuMs(child.pid) - cpuStart;
    console.log(JSON.stringify({ ...ready, result: state.result ?? 'not-completed',
        wallMs, mainThreadCpuPercent: cpuMs === null ? null : cpuMs / wallMs * 100,
        probes: probes.length, timeouts: probes.filter((probe) => !probe.ok).length }));
    if (!state.exited) {
        child.kill('SIGKILL');
    }
    assert.equal(state.exited, false, 'Worker crashed');
}

if (process.argv[2] === 'worker') {
    await worker();
} else {
    await observe();
}
